CREATE TABLE TBL_CBR_TRANSACTION_REQUEST (
    ID NUMBER(19) NOT NULL,
    SOURCE_SYSTEM VARCHAR2(20 CHAR),
    RECEIVED_AT TIMESTAMP(6) DEFAULT SYSTIMESTAMP,
    RAW_XML CLOB NOT NULL,
    PARSE_STATUS VARCHAR2(20 CHAR) DEFAULT 'RECEIVED',
    ERROR_MESSAGE VARCHAR2(1024 CHAR),
    CONSTRAINT PK_TBL_CBR_TRANSACTION_REQUEST PRIMARY KEY (ID)
);

CREATE TABLE TBL_CBR_TRANSACTION (
    ID NUMBER(19) NOT NULL,
    REQUEST_ID NUMBER(19) NOT NULL,
    CALL_REPLY_REF VARCHAR2(70 CHAR) NOT NULL,
