    PAYMENT_SERVICE_LEVEL VARCHAR2(20 CHAR) NOT NULL,
    PAYMENT_LOCAL_INSTRUMENT VARCHAR2(35 CHAR),
    PAYMENT_CATEGORY_PURPOSE VARCHAR2(35 CHAR),
    ORIGINAL_PAYMENT_TYPE VARCHAR2(10 CHAR),

    DEBTOR_AGENT VARCHAR2(11 CHAR),
    CREDITOR_AGENT VARCHAR2(11 CHAR),
    DEBTOR_ID_BIC VARCHAR2(70 CHAR),
    DEBTOR_ID_LEI VARCHAR2(70 CHAR),
    DEBTOR_ID_OTHR VARCHAR2(70 CHAR),
    DEBTOR_ID_PRVTID VARCHAR2(70 CHAR),

    CREDITOR_ID_BIC VARCHAR2(70 CHAR),
    CREDITOR_ID_LEI VARCHAR2(70 CHAR),
    CREDITOR_ID_OTHR VARCHAR2(70 CHAR),
    CREDITOR_ID_PRVTID VARCHAR2(70 CHAR),

    DEBTOR_NAME VARCHAR2(140 CHAR),
    CREDITOR_NAME VARCHAR2(140 CHAR),
    DEBTOR_IBAN VARCHAR2(34 CHAR),
    CREDITOR_IBAN VARCHAR2(34 CHAR),
    DEBTOR_ACCOUNT_NO VARCHAR2(34 CHAR),
    CREDITOR_ACCOUNT_NO VARCHAR2(34 CHAR),

    DEBTOR_POSTAL_ADDRESS VARCHAR2(256 CHAR),
    DEBTOR_TOWN VARCHAR2(70 CHAR),
    DEBTOR_COUNTRY VARCHAR2(2 CHAR),
    DEBTOR_ADDRESS VARCHAR2(140 CHAR),
    CREDITOR_POSTAL_ADDRESS VARCHAR2(256 CHAR),
    CREDITOR_TOWN VARCHAR2(70 CHAR),
    CREDITOR_COUNTRY VARCHAR2(2 CHAR),
    CREDITOR_ADDRESS VARCHAR2(140 CHAR),

    DEBTOR_RESIDENCY VARCHAR2(10 CHAR),
    CREDITOR_RESIDENCY VARCHAR2(10 CHAR),
    CHARGE_BEARER VARCHAR2(10 CHAR),
    REMITTANCE_INFO CLOB,
    REPORT_TYPE VARCHAR2(20 CHAR),
    PAYMENT_INSTRUMENT VARCHAR2(20 CHAR),
    SPECIAL_MARK VARCHAR2(20 CHAR),
    COUNTRY_CODE1 CHAR(2),
    COUNTRY_CODE2 CHAR(2),
    LOAN_NUMBER VARCHAR2(35 CHAR),
    LOAN_YEAR VARCHAR2(4 CHAR),

    DR_STATISTICAL_CODE VARCHAR2(20 CHAR),
    CR_STATISTICAL_CODE VARCHAR2(20 CHAR),

    CREATED_AT TIMESTAMP(6) DEFAULT SYSTIMESTAMP,
    UPDATED_AT TIMESTAMP(6),
    CONSTRAINT PK_TBL_CBR_TRANSACTION PRIMARY KEY (ID),
    CONSTRAINT FK_CBR_TXN_REQUEST FOREIGN KEY (REQUEST_ID) REFERENCES TBL_CBR_TRANSACTION_REQUEST (ID),
    CONSTRAINT UX_CBR_TXN_CALL_REF UNIQUE (CALL_REPLY_REF)
);


CREATE TABLE TBL_CBR_TRANSACTION_STAT (
    ID NUMBER(19) NOT NULL,
    CALL_REPLY_REF VARCHAR2(70 CHAR) NOT NULL,
    STATISTICAL_CODE VARCHAR2(35 CHAR),
    SPLIT_STAT_CODE VARCHAR2(35 CHAR),
    SPLIT_AMOUNT NUMBER(18, 2),
    SPLIT_AMOUNT_CCY CHAR(3),
    INVOICE_NUMBER VARCHAR2(35 CHAR),
    INVOICE_YEAR VARCHAR2(4 CHAR),
    CREATED_AT TIMESTAMP(6) DEFAULT SYSTIMESTAMP,
    CONSTRAINT PK_TBL_CBR_TRANSACTION_STAT PRIMARY KEY (ID),
    CONSTRAINT FK_CBR_STAT_TXN_CALL FOREIGN KEY (CALL_REPLY_REF) REFERENCES TBL_CBR_TRANSACTION (CALL_REPLY_REF) ON DELETE CASCADE
);

